    public function test_upload_accepts_bom_prefixed_header(): void
    {
        Bus::fake();
        Storage::fake('local');

        $csv = UploadedFile::fake()->createWithContent(
            'users.csv',
            "\xEF\xBB\xBFname,email,password\nJohn Doe,john@example.com,password123"
        );

