            ])
        );

        $job = ImportJob::create([
            'filename' => 'users.csv',
            'stored_path' => 'imports/users.csv',
            'status' => 'pending',
        ]);

        (new ProcessImportJob($job))->handle();

        $response = $this->get('/api/imports/' . $job->id . '/errors');

