+            'dedupe_key' => hash('sha256', $content),
+            'status' => 'processing',
+            'processing_started_at' => now()->subMinutes(31),
+        ]);
+
+        $response = $this->postJson('/api/imports', [
+            'file' => UploadedFile::fake()->createWithContent('users.csv', $content),
+        ]);
